def test_resolve_change_manifest_manual_preserves_hunks() -> None:
    g = nx.DiGraph()
    manual = {
        "entries": [
            {
                "path": "x.py",
                "node_ids": [],
                "file_change": True,
                "hunks": [{"start_line": 10, "end_line": 12}],
            }
        ]
    }
    m = resolve_change_manifest(g, manual_manifest=manual)
    assert m.entries[0].hunks[0].start_line == 10

